from PIL import Image
import numpy as np
im=np.asarray(Image.open('first_frame.png')).astype(float)
# table background color as local median excluding obj colors. approximate grayscale spread
for x in range(56,191):
 ys=[]
 for y in range(42,93):
  r,g,b=im[y,x];spread=max(r,g,b)-min(r,g,b)
  mean=(r+g+b)/3
  if mean<72 or (mean>85 and spread<32): ys.append(y)
 # contiguous longest
 runs=[];s=None;p=None
 for y in ys:
  if s is None or y>p+1:
   if s is not None:runs.append((s,p))
   s=y
  p=y
 if s is not None:runs.append((s,p))
 if runs:
  run=max(runs,key=lambda z:z[1]-z[0])
  if run[1]-run[0]>=4: print(x,run)
